    def test_unreadable_registry_vetoes_split_live_evidence(
        self, engaged: Path, monkeypatch: pytest.MonkeyPatch
    ) -> None:
        """#88R32-3: an unreadable sidecar vetoes a live unit from elsewhere; refuse.

        The orphan loop would refuse anyway (the hidden sidecar is
        unreadable), so the veto itself is pinned on the I3 voice: no
        misdirected "resolved from sidecar" deferral may fire.
        """
        import warnings

        pid, _ = _dead_pid_with_birth()
        planted = _plant_producer(
            engaged,
            uuid=_UUID_A,
            pid=pid,
            birth=424243,
            in_progress=_counts_block(2, fn="C_Digest"),
        )
        registry = Path(planted["registry"])
        hidden = Path(planted["sidecar"])
        proc = _live_sleeper()
        try:
            live_birth = durability.birth_token_for_pid(proc.pid)
            (engaged / f"{_UUID_A}-zzz.partial.json").write_text(
                json.dumps(
                    {
                        "worker_uuid": _UUID_A,
                        "unit": "b.py",
                        "pid": proc.pid,
                        "birth_token": live_birth,
                        "run_id": _RUN,
                    }
                ),
                encoding="utf-8",
            )
            with monkeypatch.context() as m:
                fired_reg = _fault_read_always(m, registry)
                fired_hidden = _fault_read_always(m, hidden)
                with warnings.catch_warnings(record=True) as caught:
                    warnings.simplefilter("always")
                    plan = durability.prepare_resume(engaged, prior_merged_jsonl=None)
            assert fired_reg and fired_hidden, "both read faults must engage"
            texts = [str(item.message) for item in caught]
            assert any("unit unidentifiable; refusing" in text for text in texts)
            assert not any("unit resolved from sidecar" in text for text in texts), (
                "the split evidence vetoes the narration; no misdirected deferral"
            )
            assert plan["barrier_ok"] is False
            assert _UUID_A in plan["unresolved"]
            assert plan["skipped_units"] == []
            assert proc.poll() is None, "refusal never fences"
        finally:
            proc.terminate()
            proc.wait(timeout=15)

