        divergent["by_module"]["m"]["buckets"]["test"]["calls"] = 3
        leaf = divergent["by_module"]["m"]["buckets"]["test"]["by_fn"]["C_Digest"]
        leaf["calls"] = 3  # 3 entries, 2 returns: refused, dropped-empty
        replay = sidecar.with_name(sidecar.name + ".tmp-4242")
