        buckets = partial["by_module"]["m"]["buckets"]
        assert buckets["setup_teardown"]["calls"] == 5
        assert buckets["test"]["calls"] == 4, "recovery attribution for orphan traffic"
        assert partial["receipts"] == [{"worker_uuid": _UUID_B, "probe_seq": 0}]
