def _quarantine_planted(tmp: Path) -> Path:
    """Rename a planted tmp exactly like _quarantine_tmp (crash simulation)."""
    target = tmp.with_name(tmp.name.replace(".tmp-", ".quarantined-", 1))
    tmp.rename(target)
    return target


