    """#88R41-3: remainder 0 = 0 passes coverage; the merged stream stays exact."""
    import warnings

    state = _r40_5_stage_retry(engaged, orphan=False)
    prior = _r40_5_prior(tmp_path, "prior.jsonl", pid=state["pid"], unit="a.py", attempt=0, total=2)
