def test_r43_f9_crash_between_link_and_unlink_completes(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """#88R43-F9: link-then-crash retries finish only the verified original's unlink."""
    import warnings

    root = tmp_path / "counters"
