    witnesses = staging.get("fold_witnesses", [])
    assert any(entry["child"] == "c" * 32 and entry["seq"] == 1 for entry in witnesses), (
        "pass 1 witnesses its folded (C,1) contributor"
    )
    stripped = _r40_b7_2_strip_snapshots(engaged)
