def test_r44_f6r4_omitted_cover_links_hint_owner(
    engaged: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """#88R44-F6r4: omitted cover uses the adoption census (no unbound delete).

    Parentless recordless retry with no report: a full-UUID filename
    marker without a body parent is staged-but-unbound. The cover
    check must link it exactly where staged adoption would (the
    cleanup census, which carries the hint owner) and hold for the
    report -- not read it vacuous on the empty collected census
    while adoption releases it.
    """
    import hashlib
    import warnings

    _r42_1_recordless_pass1(engaged, tmp_path, monkeypatch, parentless=True)
    pid, birth = _dead_pid_with_birth()
    marker_src = _plant_probe_orphan(
        engaged,
        parent_uuid=_UUID_A,
        child_uuid=_UUID_B,
        nonce="c0ffee42",
        seq=2,
        identity=None,
        counters=[["m", "C_Digest", 0, 1]],
        pid=pid,
        birth=birth,
    )
    marker = marker_src.with_name(f"probe-consumed-{_UUID_A}-2-c0ffee42.json")
    marker_src.rename(marker)
    digest = hashlib.sha256(marker.read_bytes()).hexdigest()
    staging = engaged / durability.BARRIER_STAGING_FILENAME
    saved = json.loads(staging.read_text(encoding="utf-8"))
    saved["cleanup_targets"].append({"path": str(marker), "sha256": digest})
    staging.write_text(json.dumps(saved), encoding="utf-8")
    with warnings.catch_warnings(record=True) as seen:
        warnings.simplefilter("always")
        plan = durability.prepare_resume(engaged, prior_merged_jsonl=None)
    assert plan["barrier_ok"] is True
    assert marker.exists(), "the unbound-but-linked marker holds for the report"
    assert _UUID_A in plan["retained_uuids"]
    texts = [str(found.message) for found in seen]
    assert any(
        "cannot tie staged marker" in text and "pass the committed report" in text for text in texts
    ), texts


def test_r44_f6r4_omitted_cover_routes_body_owner(
    engaged: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """#88R44-F6r4: targets group by resolved owner, not filename hint.

    Same retry, but the marker's exact body owner disagrees with its
    filename hint: the target must reach its body owner's cover
    check (which holds it unbound), not vanish under the hint
    owner's vacuous verdict while adoption releases it elsewhere.
    B's staged membership is surgical (collected + entry shape
    copied from A's proven entry: the omitted arm reads only
    run/targets, and a ghost B-hint target keeps B hint-reachable
    without judging anything itself).
    """
    import copy
    import hashlib
    import warnings

    _r42_1_recordless_pass1(engaged, tmp_path, monkeypatch, parentless=True)
    pid, birth = _dead_pid_with_birth()
    marker_src = _plant_probe_orphan(
        engaged,
        parent_uuid=_UUID_A,
        child_uuid=_UUID_B,
        nonce="c0ffee42",
        seq=2,
        identity=_f2_identity(_UUID_B, run_id=_RUN, unit="a.py"),
        counters=[["m", "C_Digest", 0, 1]],
        pid=pid,
        birth=birth,
    )
    marker = marker_src.with_name(f"probe-consumed-{_UUID_A}-2-c0ffee42.json")
    marker_src.rename(marker)
    raw = json.loads(marker.read_bytes())
    assert raw.get("parent_uuid") == _UUID_B, "the body names B against an A hint"
    digest = hashlib.sha256(marker.read_bytes()).hexdigest()
    staging = engaged / durability.BARRIER_STAGING_FILENAME
    saved = json.loads(staging.read_text(encoding="utf-8"))
    saved["cleanup_targets"].append({"path": str(marker), "sha256": digest})
    ghost = engaged / f"probe-{_UUID_B[:8]}-9-deadbeef.json.tmp-1"
    saved["cleanup_targets"].append({"path": str(ghost), "sha256": "0" * 64})
    saved["collected_uuids"].append(_UUID_B)
    saved["recordless_cleanup"][_UUID_B] = copy.deepcopy(saved["recordless_cleanup"][_UUID_A])
    staging.write_text(json.dumps(saved), encoding="utf-8")
    with warnings.catch_warnings(record=True) as seen:
        warnings.simplefilter("always")
        plan = durability.prepare_resume(engaged, prior_merged_jsonl=None)
    assert plan["barrier_ok"] is True
    assert marker.exists(), "the body-owned marker holds under its owner's check"
    assert _UUID_B in plan["retained_uuids"]
    texts = [str(found.message) for found in seen]
    assert any(
        "cannot tie staged marker" in text and "pass the committed report" in text for text in texts
    ), texts


def test_r43_f1_durable_authority_shape_and_receipt_tamper(
    engaged: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """#88R43-F1: the entry carries receipts+identity; tampered claims hold the retry."""
    import json
    import warnings

    _, probe, prior1, _ = _r42_1_recordless_pass1(engaged, tmp_path, monkeypatch, parentless=True)
    staging = engaged / durability.BARRIER_STAGING_FILENAME
    saved = staging.read_text(encoding="utf-8")
    entry = json.loads(saved)["recordless_cleanup"][_UUID_A]
    assert entry.get("receipts") == [{"worker_uuid": _UUID_B, "probe_seq": 1}]
    session = json.loads(prior1.read_text(encoding="utf-8").splitlines()[2])
    assert entry.get("publication") == durability._publication_digest(session)
    tampered = json.loads(saved)
    tampered_entry = tampered["recordless_cleanup"][_UUID_A]
    tampered_entry["receipts"].append({"worker_uuid": "c" * 32, "probe_seq": 2})
    tampered_entry["publication"] = "0" * 64
    staging.write_text(json.dumps(tampered), encoding="utf-8")
    with warnings.catch_warnings(record=True) as seen_hold:
        warnings.simplefilter("always")
        held = durability.prepare_resume(engaged, prior_merged_jsonl=prior1)
    assert held["barrier_ok"] is True
    hold_texts = [str(found.message) for found in seen_hold]
    assert any("recordless cleanup" in text and "receipt" in text for text in hold_texts)
    assert probe.exists(), "the tampered claim the winner lacks holds the probe"
    assert _UUID_A in held["retained_uuids"]
    staging.write_text(saved, encoding="utf-8")
    with warnings.catch_warnings(record=True) as seen_free:
        warnings.simplefilter("always")
        plan = durability.prepare_resume(engaged, prior_merged_jsonl=prior1)
    assert plan["barrier_ok"] is True
    free_texts = [str(found.message) for found in seen_free]
    assert not probe.exists(), "the persisted identity re-establishes authority"
    assert not any("strict retry held" in text for text in free_texts), free_texts
    assert not any("recordless cleanup" in text for text in free_texts), free_texts


def test_r44_f6a_dropped_receipts_hold_replacement(
    engaged: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """#88R44-F6a pin: a winner dropping the staged receipts holds (dropped arm).

    Complement to the receipt-tamper test: where that appends a claim
    the winner lacks, this replaces the staged claim wholesale -- the
    dropped-receipt arm (not the digest short-circuit, which already
    binds receipts) withholds the probe.
    """
    import json
    import warnings

    _, probe, prior1, _ = _r42_1_recordless_pass1(engaged, tmp_path, monkeypatch, parentless=True)
    raw = [json.loads(line) for line in prior1.read_text(encoding="utf-8").splitlines()]
    raw[2]["receipts"] = [{"worker_uuid": "c" * 32, "probe_seq": 2}]
    prior1.write_text("".join(json.dumps(entry) + "\n" for entry in raw), encoding="utf-8")
    with warnings.catch_warnings(record=True) as seen:
        warnings.simplefilter("always")
        plan = durability.prepare_resume(engaged, prior_merged_jsonl=prior1)
    assert plan["barrier_ok"] is True
    assert probe.exists(), "disjoint receipts hold the probe"
    assert _UUID_A in plan["retained_uuids"]
    texts = [str(found.message) for found in seen]
    assert any("recordless cleanup" in text for text in texts), texts


def test_r43_f1_receipt_superset_replacement_holds(
    engaged: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """#88R43-F1 as REVERSED by #88R44-G7: an unproved superset holds.

    Was test_r43_f1_receipt_superset_replacement_converges: the
    replacement adds a claim (same aggregate, receipt superset) but
    carries no proof tying the held target's version to the new
    publication, so the probe holds loudly instead of converging.
    """
    import json
    import warnings

    _, probe, prior, _ = _r42_1_recordless_pass1(engaged, tmp_path, monkeypatch, parentless=True)
    raw = [json.loads(line) for line in prior.read_text(encoding="utf-8").splitlines()]
    raw[2]["receipts"] = [
        {"worker_uuid": _UUID_B, "probe_seq": 1},
        {"worker_uuid": "c" * 32, "probe_seq": 2},
    ]
    prior.write_text("".join(json.dumps(entry) + "\n" for entry in raw), encoding="utf-8")
    with warnings.catch_warnings(record=True) as seen:
        warnings.simplefilter("always")
        plan = durability.prepare_resume(engaged, prior_merged_jsonl=prior)
    assert plan["barrier_ok"] is True
    texts = [str(found.message) for found in seen]
    assert probe.exists(), "the unproved replacement releases nothing"
    assert _UUID_A in plan["retained_uuids"]
    assert any("recordless cleanup" in text for text in texts), texts
    assert plan["cache_records"] == {}


