# --------------------------------------------------------------------------
# R44-F4 round 2: adjudicated runs + ownership gate (RED)
# --------------------------------------------------------------------------


def test_r44_f4r2_staged_history_revokes_adopted_probe(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """#88R44-F4r2: earn and shortcut recheck read the adjudicated run, not bytes.

    Extends test_r44_f4a_staged_run_revokes_adopted_probe by one pass:
    pass 2 revokes the unstamped probe while B's recovery is fresh;
    pass 3 faces the same recovery as staged history. The shortcut
    recheck and the earn-time cover writer must key the staged target
    to its adjudicated run (R1) at all three points (earn, recheck,
    revocation) -- re-deriving "" from the carrier bytes misses the
    recovery and deletes the probe.
    """
    import warnings

    base = tmp_path
    root = base / "counters"
    root.mkdir()
    pid, birth = _dead_pid_with_birth()
    fix = _plant_producer(
        root,
        uuid=_UUID_A,
        pid=pid,
        birth=birth,
        in_progress=_counts_block(2, fn="C_Digest"),
    )
    key = _lost_key(_UUID_B, 1)
    probe = _plant_probe_orphan(
        root,
        parent_uuid=_UUID_A,
        child_uuid="e" * 32,
        seq=0,
        counters=[],
        identity=None,
        pid=pid,
        birth=birth,
        probes_lost=1,
    )
    raw = json.loads(probe.read_bytes())
    raw["lost_keys"] = [key]
    probe.write_text(json.dumps(raw), encoding="utf-8")
    blocker = _R426UnlinkBlocker(monkeypatch, {probe.name})
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        first = durability.prepare_resume(root, prior_merged_jsonl=None)
    assert first["barrier_ok"] is True
    assert probe.exists(), "pass 1 holds the blocked probe"
    assert not Path(fix["sidecar"]).exists(), "pass 1 converges the keyless parent"
    staging_path = root / durability.BARRIER_STAGING_FILENAME
    staging = json.loads(staging_path.read_text(encoding="utf-8"))
    entries = [row for row in staging["cleanup_targets"] if row["path"] == str(probe)]
    assert len(entries) == 1, "pass 1 stages the probe's retry"
    assert entries[0].get("run") == _RUN, "the staged target persists its adjudicated run"
    blocker.blocked = False
    pid_b, birth_b = _dead_pid_with_birth()
    _plant_producer(
        root, uuid=_UUID_B, pid=pid_b, birth=birth_b, in_progress=_counts_block(2, fn="C_Digest")
    )
    _plant_probe_orphan(
        root,
        parent_uuid=_UUID_B,
        child_uuid="c" * 32,
        seq=1,
        counters=[["m", "C_Digest", 9, 2]],
        identity=_f2_identity(_UUID_B),
        pid=pid_b,
        birth=birth_b,
    )
    with warnings.catch_warnings(record=True) as seen:
        warnings.simplefilter("always")
        second = durability.prepare_resume(root, prior_merged_jsonl=None)
    assert second["barrier_ok"] is True
    assert probe.exists(), "pass 2 revokes the adopted probe via its staged run"
    texts = [str(found.message) for found in seen]
    assert any(
        f"({_UUID_B}, 1)" in text and "cancelled by" in text and "this-pass recovery" in text
        for text in texts
    ), texts
    staging2 = json.loads(staging_path.read_text(encoding="utf-8"))
    entries2 = [row for row in staging2["cleanup_targets"] if row["path"] == str(probe)]
    assert len(entries2) == 1, "pass 2 re-stages the revoked probe's retry"
    with warnings.catch_warnings(record=True) as seen3:
        warnings.simplefilter("always")
        third = durability.prepare_resume(root, prior_merged_jsonl=None)
    assert third["barrier_ok"] is True
    assert probe.exists(), "pass 3 holds the adopted probe against staged history"
    texts3 = [str(found.message) for found in seen3]
    assert any(f"({_UUID_B}, 1)" in text and "cancelled by" in text for text in texts3), texts3


def test_r44_f4r2_ambiguous_covered_rows_hold_on_ownership(tmp_path: Path) -> None:
    """#88R44-F4r2 [A]: coverage without unique ownership never consumes.

    The [A] repro against test_r44_f4_ambiguous_covered_probe_holds:
    same colliding producers and legacy probe, but the
    receipt-holding checkpoint ALSO covers the orphan's return rows,
    so every volume check passes. Coverage is a receipt claim, not
    parenthood proof -- under a prefix collision the orphan could
    belong to any collider, so the would-be success still retains
    loudly (ownership gate) instead of consuming silently. The
    covering producer converges without the orphan (file-level skip,
    like the routing gate); the existing volume-deficit voices stay
    untouched (that pin still holds earlier, at the volume check).
    """
    import warnings

    from pkcs11_check.raw.rv import ckr_name

    base = tmp_path
    root = base / "counters"
    root.mkdir()
    pid, birth = _dead_pid_with_birth()
    first = "a" * 31 + "0"
    second = "a" * 31 + "1"
    receipt = {"worker_uuid": "e" * 32, "probe_seq": 0}
    checkpoint = _counts_block(5, fn="C_Digest")
    checkpoint["by_module"]["m"]["buckets"]["test"]["by_fn"]["C_Digest"]["by_rv"] = {
        "9": {"name": ckr_name(9), "count": 5}
    }
    _plant_producer(
        root,
        uuid=first,
        pid=pid,
        birth=birth,
        in_progress=checkpoint,
        receipts=[receipt],
    )
    _plant_producer(root, uuid=second, pid=pid, birth=birth, in_progress=_counts_block(7))
    probe = _plant_probe_orphan(
        root,
        parent_uuid=first,
        child_uuid="e" * 32,
        seq=0,
        counters=[["m", "C_Digest", 9, 2]],
        identity=None,
        pid=pid,
        birth=birth,
    )
    raw = json.loads(probe.read_bytes())
    raw["lost_keys"] = [_lost_key(_UUID_B, 1)]
    probe.write_text(json.dumps(raw), encoding="utf-8")
    child = _write_jsonl(
        base / "child.jsonl",
        [
            {"$report_type": "SessionStart"},
            _marker("a.py", 0),
            {
                "$report_type": "TestReport",
                "nodeid": "a.py::test_first",
                "when": "setup",
                "outcome": "passed",
            },
        ],
    )
    with warnings.catch_warnings(record=True) as seen:
        warnings.simplefilter("always")
        records = durability.collect_unit(
            root, unit="a.py", child_jsonl=child, status="passed", returncode=0
        )
    assert probe.exists(), "coverage without ownership never consumes its carrier"
    totals = sorted(rec["total_calls"] for rec in records if "total_calls" in rec)
    assert totals == [5, 7], "the covering producer converges without the orphan"
    texts = [str(found.message) for found in seen]
    assert any("ambiguous probe orphan" in text and "proves no parent" in text for text in texts), (
        texts
    )


def test_r44_ar3_ambiguous_covered_divergent_tmps_hold_before_quarantine(
    tmp_path: Path,
) -> None:
    """#88R44-[A]r3: ownership gates fencing/mutation/cleanup, not the fold.

    The R3 [A] repro: the F4r2 covered prefix-collision fixture plus
    two divergent, legacy-stamped rewrite tmps. Ownership is unproved
    (legacy linkage under a prefix collision, checkpoint cover but no
    marker), so collect must hold BEFORE replay -- the rewrite tmps
    stay at their original paths (no quarantine move), the probe
    retains, the covering producer converges without the orphan, and
    the hold names its exit. Pre-fix, replay quarantines both tmps
    first and the pass defers with a mistargeted "marker coverage"
    voice.
    """
    import warnings

    from pkcs11_check.raw.rv import ckr_name

    base = tmp_path
    root = base / "counters"
    root.mkdir()
    pid, birth = _dead_pid_with_birth()
    first = "a" * 31 + "0"
    second = "a" * 31 + "1"
    receipt = {"worker_uuid": "e" * 32, "probe_seq": 0}
    checkpoint = _counts_block(5, fn="C_Digest")
    checkpoint["by_module"]["m"]["buckets"]["test"]["by_fn"]["C_Digest"]["by_rv"] = {
        "9": {"name": ckr_name(9), "count": 5}
    }
    _plant_producer(
        root,
        uuid=first,
        pid=pid,
        birth=birth,
        in_progress=checkpoint,
        receipts=[receipt],
    )
    _plant_producer(root, uuid=second, pid=pid, birth=birth, in_progress=_counts_block(7))
    probe = _plant_probe_orphan(
        root,
        parent_uuid=first,
        child_uuid="e" * 32,
        seq=0,
        counters=[["m", "C_Digest", 9, 2], ["m", "C_Digest", None, 1]],
        identity=None,
        pid=pid,
        birth=birth,
    )
    raw = json.loads(probe.read_bytes())
    raw["lost_keys"] = [_lost_key(_UUID_B, 1)]
    probe.write_text(json.dumps(raw), encoding="utf-8")

    def _legacy(payload: dict[str, Any]) -> dict[str, Any]:
        for stamp in ("parent_uuid", "run_id", "unit", "attempt", "role", "isolation"):
            payload.pop(stamp, None)
        return payload

    tmp_a = _plant_probe_tmp(
        probe,
        _legacy(
            _probe_tmp_payload("e" * 32, 0, [["m", "C_Digest", 9, 2], ["m", "C_Digest", 0, 1]])
        ),
        pid=1001,
    )
    tmp_b = _plant_probe_tmp(
        probe,
        _legacy(
            _probe_tmp_payload("e" * 32, 0, [["m", "C_Digest", 9, 2], ["m", "C_Digest", 1, 1]])
        ),
        pid=1002,
    )
    child = _write_jsonl(
        base / "child.jsonl",
        [
            {"$report_type": "SessionStart"},
            _marker("a.py", 0),
            {
                "$report_type": "TestReport",
                "nodeid": "a.py::test_first",
                "when": "setup",
                "outcome": "passed",
            },
        ],
    )
    with warnings.catch_warnings(record=True) as seen:
        warnings.simplefilter("always")
        records = durability.collect_unit(
            root, unit="a.py", child_jsonl=child, status="passed", returncode=0
        )
    assert tmp_a.exists(), "unowned rewrites never move to quarantine"
    assert tmp_b.exists(), "unowned rewrites never move to quarantine"
    assert list(root.glob("*.quarantined-*")) == [], "no quarantine move fires"
    assert probe.exists(), "coverage without ownership never consumes its carrier"
    totals = sorted(rec["total_calls"] for rec in records if "total_calls" in rec)
    assert totals == [5, 7], "the covering producer converges without the orphan"
    texts = [str(found.message) for found in seen]
    assert any(
        "ambiguous probe orphan" in text
        and "proves no parent" in text
        and "establish the owner from independent evidence" in text
        for text in texts
    ), texts
    assert not any("divergent rewrites under marker coverage" in text for text in texts), texts


def test_r44_ar4_ambiguity_survives_collider_retry(tmp_path: Path) -> None:
    """#88R44-[A]r4: an ambiguous hold pins its colliders across retries.

    The R4 repro: two colliding parents in different units, unit A's
    checkpoint covering a legacy orphan. The first collect holds the
    orphan -- and must retain A's registry as ambiguity evidence,
    so the second collect (B's unit) still sees the collision and
    holds again instead of folding the orphan into B as a false
    unique match.
    """
    import warnings

    from pkcs11_check.raw.rv import ckr_name

    base = tmp_path
    root = base / "counters"
    root.mkdir()
    pid, birth = _dead_pid_with_birth()
    first = "a" * 31 + "0"
    second = "a" * 31 + "1"
    checkpoint = _counts_block(5, fn="C_Digest")
    checkpoint["by_module"]["m"]["buckets"]["test"]["by_fn"]["C_Digest"]["by_rv"] = {
        "9": {"name": ckr_name(9), "count": 5}
    }
    planted_a = _plant_producer(
        root,
        uuid=first,
        pid=pid,
        birth=birth,
        unit="a.py",
        in_progress=checkpoint,
        receipts=[{"worker_uuid": "e" * 32, "probe_seq": 0}],
    )
    _plant_producer(
        root, uuid=second, pid=pid, birth=birth, unit="b.py", in_progress=_counts_block(7)
    )
    probe = _plant_probe_orphan(
        root,
        parent_uuid=first,
        child_uuid="e" * 32,
        seq=0,
        counters=[["m", "C_Digest", 9, 2]],
        identity=None,
        pid=pid,
        birth=birth,
    )
    raw = json.loads(probe.read_bytes())
    raw["lost_keys"] = [_lost_key(_UUID_B, 1)]
    probe.write_text(json.dumps(raw), encoding="utf-8")

    def _child(name: str, nodeid: str) -> Path:
        return _write_jsonl(
            base / name,
            [
                {"$report_type": "SessionStart"},
                _marker("a.py", 0),
                {
                    "$report_type": "TestReport",
                    "nodeid": nodeid,
                    "when": "setup",
                    "outcome": "passed",
                },
            ],
        )

    with warnings.catch_warnings(record=True) as seen_a:
        warnings.simplefilter("always")
        records_a = durability.collect_unit(
            root,
            unit="a.py",
            child_jsonl=_child("child-a.jsonl", "a.py::test_first"),
            status="passed",
            returncode=0,
        )
    assert probe.exists(), "the first collect holds the ambiguous probe"
    assert Path(planted_a["registry"]).exists(), "A's registry pins as ambiguity evidence"
    totals_a = sorted(rec["total_calls"] for rec in records_a if "total_calls" in rec)
    assert totals_a == [5], "A converges without the orphan"
    texts_a = [str(found.message) for found in seen_a]
    assert any("ambiguous probe orphan" in text for text in texts_a), texts_a
    assert any("retained as ambiguity evidence" in text for text in texts_a), texts_a
    with warnings.catch_warnings(record=True) as seen_b:
        warnings.simplefilter("always")
        records_b = durability.collect_unit(
            root,
            unit="b.py",
            child_jsonl=_child("child-b.jsonl", "b.py::test_second"),
            status="passed",
            returncode=0,
        )
    assert probe.exists(), "the retry still sees the collision and holds"
    totals_b = sorted(rec["total_calls"] for rec in records_b if "total_calls" in rec)
    assert totals_b == [7], "the orphan never folds into B as a false unique match"
    texts_b = [str(found.message) for found in seen_b]
    # B is not the collision reporter, so its hold is silent -- but its
    # pin voice fires, naming the hold it preserves evidence for.
    assert any("retained as ambiguity evidence" in text for text in texts_b), texts_b


def test_r44_ar5_pinned_retry_emits_no_phantom_loss(tmp_path: Path) -> None:
    """#88R44-[A]r5: a pinned registry-only retry emits nothing.

    After both units' sidecars consume, a third collect on a fresh
    child re-holds the orphan (both registries still known) -- and
    must not emit a CallCountersLost for already-published evidence.
    """
